{
  "rules": [
    {
      "category": "just_cause_eviction",
      "title": "Defense to No-Fault Eviction During School Year for Households with Children or Educators",
      "requirement": "Landlords may not evict a tenant under specified no-fault grounds during the school year if a child under 18 or an educator resides in the unit, has a custodial or family relationship with a tenant, and the tenant has resided there for 12 months or more.",
      "requirement_es": "Los propietarios no pueden desalojar a un inquilino bajo ciertas causas sin culpa durante el año escolar si un menor de 18 años o un educador reside en la unidad, tiene una relación de custodia o familiar con un inquilino, y el inquilino ha vivido allí durante 12 meses o más.",
      "key_value": null,
      "coverage_conditions": {
        "type": "AND",
        "clauses": [
          {
            "field": "tenancy_length_months",
            "operator": ">=",
            "value": 12,
            "note": "the tenant has resided in the unit for 12 months or more"
          }
        ]
      },
      "exemptions": [
        {
          "description": "Temporary evictions to perform mandatory seismic retrofitting work under Building Code Chapter 34B with required notice and compensation.",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "owner_type",
                "operator": "==",
                "value": "__unknowable__"
              }
            ]
          }
        }
      ],
      "effective_date": null,
      "superseded_date": null,
      "status": "enacted",
      "precedence": {
        "relationship": "stacks_with",
        "target_scope": "none",
        "source_language": null
      },
      "penalty": null,
      "source_citation": "S.F. Admin. Code § 37.9(j)(1)",
      "quote": {
        "chunk": "c1887",
        "start_words": "It shall be a defense to an eviction",
        "end_words": "falls during the school year."
      },
      "confidence": 0.95
    },
    {
      "category": "just_cause_eviction",
      "title": "Written Warning and Ten-Day Right to Cure Before Fault Evictions",
      "requirement": "Landlords must provide tenants with a written warning and a 10-day period to cure alleged lease violations before pursuing eviction under Sections 37.9(a)(2), (3), (4), (5), or (6).",
      "requirement_es": "Los propietarios deben proporcionar a los inquilinos una advertencia por escrito y un período de 10 días para subsanar los presuntos incumplimientos del contrato antes de iniciar un desalojo según las Secciones 37.9(a)(2), (3), (4), (5) o (6).",
      "key_value": {
        "label": "cure period",
        "value": "10 days"
      },
      "coverage_conditions": {
        "type": "ALWAYS",
        "clauses": []
      },
      "exemptions": [
        {
          "description": "Lease agreements providing a longer notice and cure period.",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "owner_type",
                "operator": "==",
                "value": "__unknowable__"
              }
            ]
          }
        },
        {
          "description": "Evictions where the tenant causes or creates an imminent risk of physical harm to persons or property.",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "owner_type",
                "operator": "==",
                "value": "__unknowable__"
              }
            ]
          }
        }
      ],
      "effective_date": null,
      "superseded_date": null,
      "status": "enacted",
      "precedence": {
        "relationship": "stacks_with",
        "target_scope": "none",
        "source_language": null
      },
      "penalty": null,
      "source_citation": "S.F. Admin. Code § 37.9(o)",
      "quote": {
        "chunk": "c1984",
        "start_words": "The grounds for recovering possession set forth in Sections 37.9(a))(2),",
        "end_words": "in the initiation of eviction proceedings."
      },
      "confidence": 0.95
    },
    {
      "category": "rent_increase_limit",
      "title": "Rent Limitation on Ellis Act Withdrawn Units Re-Offered for Rent",
      "requirement": "If a unit withdrawn under the Ellis Act is offered for rent within 5 years of filing the notice of intent to withdraw or within 5 years of withdrawal, the rent cannot exceed the lawful rent in effect at the time of the notice plus authorized annual increases.",
      "requirement_es": "Si una unidad retirada bajo la Ley Ellis se vuelve a ofrecer en alquiler dentro de los 5 años posteriores a la notificación de intención de retiro o dentro de los 5 años posteriores al retiro, el alquiler no puede exceder el monto legal vigente al momento de la notificación más los aumentos anuales autorizados.",
      "key_value": {
        "label": "re-rental period",
        "value": "5 years"
      },
      "coverage_conditions": {
        "type": "ALWAYS",
        "clauses": []
      },
      "exemptions": [
        {
          "description": "New tenancies lawfully created before January 1, 2003 following a lawful withdrawal under Section 37.9(a)(13).",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "owner_type",
                "operator": "==",
                "value": "__unknowable__"
              }
            ]
          }
        }
      ],
      "effective_date": null,
      "superseded_date": null,
      "status": "enacted",
      "precedence": {
        "relationship": "supersedes",
        "target_scope": "local",
        "source_language": "shall prevail over any conflicting provision of law authorizing the landlord to establish the rental rate upon the initial hiring of the unit."
      },
      "penalty": null,
      "source_citation": "S.F. Admin. Code § 37.9A(a)(1)",
      "quote": {
        "chunk": "c1994",
        "start_words": "Except as provided in Section 37.9A(a)(2) below,",
        "end_words": "increases available under this Chapter 37."
      },
      "confidence": 0.95
    },
    {
      "category": "just_cause_eviction",
      "title": "Relocation Payments for Ellis Act Evictions Filed On or After September 1, 2022",
      "requirement": "For Ellis Act evictions noticed on or after September 1, 2022, landlords must pay $10,000 per eligible tenant (up to $30,000 per unit), plus an additional $6,700 for each eligible tenant who is 62 or older or disabled.",
      "requirement_es": "Para los desalojos bajo la Ley Ellis notificados a partir del 1 de septiembre de 2022, los propietarios deben pagar $10,000 por inquilino elegible (hasta un máximo de $30,000 por unidad), más un pago adicional de $6,700 por cada inquilino de 62 años o más o con discapacidad.",
      "key_value": {
        "label": "relocation payment per eligible tenant",
        "value": "$10,000 (plus $6,700 for senior/disabled)"
      },
      "coverage_conditions": {
        "type": "ALWAYS",
        "clauses": []
      },
      "exemptions": [],
      "effective_date": "2022-09-01",
      "superseded_date": null,
      "status": "enacted",
      "precedence": {
        "relationship": "stacks_with",
        "target_scope": "none",
        "source_language": null
      },
      "penalty": null,
      "source_citation": "S.F. Admin. Code § 37.9A(e)(2)",
      "quote": {
        "chunk": "c2096",
        "start_words": "Where a landlord seeks eviction based upon",
        "end_words": "timing of which is set forth in that subsection."
      },
      "confidence": 0.95
    },
    {
      "category": "rent_increase_limit",
      "title": "Rent Limitation on Re-Rental Following Owner or Relative Move-In Eviction",
      "requirement": "If a unit vacated pursuant to an owner or relative move-in eviction is offered for rent within 5 years, the rent must not exceed what it would have been had the displaced tenant remained in continuous occupancy.",
      "requirement_es": "Si una unidad desalojada debido a la mudanza del propietario o un familiar se ofrece en alquiler dentro de los 5 años siguientes, el alquiler no puede exceder lo que habría sido si el inquilino desalojado hubiera permanecido en ocupación continua.",
      "key_value": {
        "label": "restriction duration",
        "value": "5 years"
      },
      "coverage_conditions": {
        "type": "ALWAYS",
        "clauses": []
      },
      "exemptions": [],
      "effective_date": null,
      "superseded_date": null,
      "status": "enacted",
      "precedence": {
        "relationship": "stacks_with",
        "target_scope": "none",
        "source_language": null
      },
      "penalty": "Charging excessive rent within 5 years of the notice to quit is a misdemeanor subject to a mandatory fine of $1,000 and up to six months imprisonment.",
      "source_citation": "S.F. Admin. Code § 37.9B(a)",
      "quote": {
        "chunk": "c2206",
        "start_words": "Any rental unit which a tenant vacates after receiving a notice to quit based on",
        "end_words": "remained subject to this Chapter 37."
      },
      "confidence": 0.95
    },
    {
      "category": "just_cause_eviction",
      "title": "Right of First Refusal Following Owner Move-In Eviction",
      "requirement": "A landlord who re-offers a unit for rent within 5 years of serving an owner move-in notice to quit must first offer the unit to the displaced tenant in writing, giving the tenant 30 days to accept and 45 days to reoccupy.",
      "requirement_es": "Un propietario que vuelva a ofrecer una unidad en alquiler dentro de los 5 años posteriores a la notificación de mudanza del propietario debe ofrecerla primero al inquilino desalojado por escrito, otorgándole 30 días para aceptar y 45 días para reocupar.",
      "key_value": {
        "label": "re-offer right duration",
        "value": "5 years"
      },
      "coverage_conditions": {
        "type": "ALWAYS",
        "clauses": []
      },
      "exemptions": [],
      "effective_date": "2018-01-01",
      "superseded_date": null,
      "status": "enacted",
      "precedence": {
        "relationship": "stacks_with",
        "target_scope": "none",
        "source_language": null
      },
      "penalty": null,
      "source_citation": "S.F. Admin. Code § 37.9B(b)(2)",
      "quote": {
        "chunk": "c2229",
        "start_words": "For notices to vacate served on or after January 1, 2018,",
        "end_words": "within 45 days of receipt of the offer."
      },
      "confidence": 0.95
    },
    {
      "category": "just_cause_eviction",
      "title": "Relocation Payments for Covered No-Fault Evictions",
      "requirement": "For covered no-fault evictions under Sections 37.9(a)(8), (10), (11), or (12), the landlord must pay each authorized occupant residing for 12+ months a base relocation fee ($4,500 base amount, capped at $13,500 per unit, adjusted annually by CPI), plus an additional $3,000 (plus CPI) for seniors, disabled tenants, or households with minor children.",
      "requirement_es": "Para los desalojos sin culpa cubiertos según las Secciones 37.9(a)(8), (10), (11) o (12), el propietario debe pagar a cada ocupante autorizado con más de 12 meses de residencia una compensación base ($4,500 base, máximo $13,500 por unidad, ajustado anualmente por IPC), más $3,000 adicionales (más IPC) para adultos mayores, personas con discapacidad o familias con menores.",
      "key_value": {
        "label": "base relocation payment per tenant",
        "value": "$4,500 (CPI adjusted; max $13,500/unit)"
      },
      "coverage_conditions": {
        "type": "AND",
        "clauses": [
          {
            "field": "tenancy_length_months",
            "operator": ">=",
            "value": 12,
            "note": "who has resided in the unit for 12 or more months"
          }
        ]
      },
      "exemptions": [
        {
          "description": "Temporary displacement under Section 37.9(a)(11) for less than 20 days is governed by California Civil Code Section 1947.9.",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "owner_type",
                "operator": "==",
                "value": "__unknowable__"
              }
            ]
          }
        }
      ],
      "effective_date": "2006-12-22",
      "superseded_date": null,
      "status": "enacted",
      "precedence": {
        "relationship": "stacks_with",
        "target_scope": "none",
        "source_language": null
      },
      "penalty": null,
      "source_citation": "S.F. Admin. Code § 37.9C(a)-(e)",
      "quote": {
        "chunk": "c2300",
        "start_words": "Each Eligible Tenant receiving a Covered No-Fault",
        "end_words": "relocation expenses to all Eligible Tenants in the same unit."
      },
      "confidence": 0.95
    },
    {
      "category": "just_cause_eviction",
      "title": "Tenant Protections in Foreclosed Properties",
      "requirement": "A successor owner who takes title to residential property through foreclosure cannot evict existing tenants except for just cause under Section 37.9 or at the expiration of the tenant's existing lease, whichever is later, and must provide statutory notice of rights within 15 days.",
      "requirement_es": "Un sucesor que adquiera el título de una propiedad residencial mediante ejecución hipotecaria no puede desalojar a los inquilinos existentes excepto por causa justa según la Sección 37.9 o al término del contrato de arrendamiento existente, lo que ocurra más tarde, y debe entregar un aviso sobre sus derechos dentro de 15 días.",
      "key_value": {
        "label": "notice deadline after foreclosure",
        "value": "15 days"
      },
      "coverage_conditions": {
        "type": "ALWAYS",
        "clauses": []
      },
      "exemptions": [],
      "effective_date": "2010-04-25",
      "superseded_date": null,
      "status": "enacted",
      "precedence": {
        "relationship": "stacks_with",
        "target_scope": "none",
        "source_language": null
      },
      "penalty": "Failure to provide required foreclosure notice is an affirmative defense to an eviction action.",
      "source_citation": "S.F. Admin. Code § 37.9D(b), (e)",
      "quote": {
        "chunk": "c2330",
        "start_words": "Any residential tenant who was in possession",
        "end_words": "whichever occurs later."
      },
      "confidence": 0.95
    },
    {
      "category": "just_cause_eviction",
      "title": "Right to Rescind Tenant Buyout Agreements",
      "requirement": "Tenants entering into a buyout agreement have the right to cancel the agreement for up to 45 days after execution, and landlords must give mandatory disclosures before buyout negotiations begin.",
      "requirement_es": "Los inquilinos que firmen un acuerdo de compraventa voluntaria (buyout) tienen derecho a rescindir el acuerdo dentro de los 45 días posteriores a la firma, y los propietarios deben proporcionar avisos informativos obligatorios antes de iniciar las negociaciones.",
      "key_value": {
        "label": "rescission period",
        "value": "45 days"
      },
      "coverage_conditions": {
        "type": "ALWAYS",
        "clauses": []
      },
      "exemptions": [
        {
          "description": "Agreements to settle a pending unlawful detainer action.",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "owner_type",
                "operator": "==",
                "value": "__unknowable__"
              }
            ]
          }
        }
      ],
      "effective_date": "2015-03-07",
      "superseded_date": null,
      "status": "enacted",
      "precedence": {
        "relationship": "stacks_with",
        "target_scope": "none",
        "source_language": "Notwithstanding Section 37.3 or any other provision in City law"
      },
      "penalty": "Civil penalty up to $500 for disclosure violations; penalty up to 50% of tenant's damages for agreement violations; up to $100/day administrative penalty (max $20,000) for failing to file with Rent Board.",
      "source_citation": "S.F. Admin. Code § 37.9E(g)",
      "quote": {
        "chunk": "c2487",
        "start_words": "A tenant shall have the right to rescind a Buyout Agreement",
        "end_words": "rescinded the Buyout Agreement."
      },
      "confidence": 0.95
    },
    {
      "category": "just_cause_eviction",
      "title": "Prohibition of Fixed-Term Agreements Mandating Move-Out",
      "requirement": "Any lease provision purporting to require a tenant to vacate at the expiration of a stated term or treating the failure to vacate at term end as just cause for eviction is void as contrary to public policy, and a landlord may not attempt to recover possession without just cause.",
      "requirement_es": "Cualquier cláusula de arrendamiento que intente exigir al inquilino desocupar al vencer un plazo determinado o califique el no desocupar al término del plazo como causa justa de desalojo es nula, y el propietario no puede intentar recuperar la posesión sin causa justa.",
      "key_value": null,
      "coverage_conditions": {
        "type": "ALWAYS",
        "clauses": []
      },
      "exemptions": [
        {
          "description": "Tenancies expressly authorized by Chapter 37 to be fixed-term or evictable without just cause.",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "owner_type",
                "operator": "==",
                "value": "__unknowable__"
              }
            ]
          }
        }
      ],
      "effective_date": "2020-06-22",
      "superseded_date": null,
      "status": "enacted",
      "precedence": {
        "relationship": "stacks_with",
        "target_scope": "none",
        "source_language": null
      },
      "penalty": "Civil penalties up to two times the amount paid or received for use of the unit, plus attorney's fees.",
      "source_citation": "S.F. Admin. Code § 37.9F(b)",
      "quote": {
        "chunk": "c2547",
        "start_words": "Consistent with Section 37.9(a)(2) and Section 37.9(e), any provision",
        "end_words": "of the unit without just cause."
      },
      "confidence": 0.95
    },
    {
      "category": "algorithmic_rent_setting",
      "title": "Prohibition on Sale and Use of Algorithmic Rental Devices",
      "requirement": "It is unlawful to sell, license, or provide to San Francisco landlords, or for a landlord to use, any algorithmic device (such as revenue management software using non-public competitor data) to set, recommend, or advise on rents or occupancy levels.",
      "requirement_es": "Es ilegal vender, licenciar o proporcionar a los propietarios de San Francisco, o que un propietario use, cualquier dispositivo algorítmico (como software de gestión de ingresos que use datos no públicos de competidores) para fijar, recomendar o asesorar sobre montos de alquiler o niveles de ocupación.",
      "key_value": null,
      "coverage_conditions": {
        "type": "ALWAYS",
        "clauses": []
      },
      "exemptions": [
        {
          "description": "Reports publishing existing rental data in an aggregated manner without recommending future rents or occupancy levels.",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "owner_type",
                "operator": "==",
                "value": "__unknowable__"
              }
            ]
          }
        },
        {
          "description": "Products used for establishing rent or income limits in accordance with affordable housing program guidelines.",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "rent_subsidized",
                "operator": "==",
                "value": true,
                "note": "affordable housing program guidelines"
              }
            ]
          }
        }
      ],
      "effective_date": "2024-10-14",
      "superseded_date": null,
      "status": "enacted",
      "precedence": {
        "relationship": "stacks_with",
        "target_scope": "none",
        "source_language": null
      },
      "penalty": "Civil penalties up to $1,000 per violation, injunctive relief, restitution/return of illegal profits, damages, and reasonable attorney's fees.",
      "source_citation": "S.F. Admin. Code § 37.10C(a), (b)",
      "quote": {
        "chunk": "c2767",
        "start_words": "It shall be unlawful to sell, license, or otherwise provide",
        "end_words": "dwelling units in San Francisco."
      },
      "confidence": 0.95
    }
  ]
}
